% 习题 1.3.1 数值验证
a = [2 -1 2];  b = [3 0 4];  c = [1 2 1];
ab_dot   = dot(a, b);
angle_ab = acosd(ab_dot / (norm(a) * norm(b)));
ab_cross = cross(a, b);
mix1     = dot(cross(a, b), c);
mix2     = det([a; b; c]);
fprintf('a.b = %g, angle = %.4f deg\n', ab_dot, angle_ab);
fprintf('a x b = [%g %g %g], [a,b,c] = %g (det = %g)\n', ab_cross, mix1, mix2);

% 随机检验 1000 组向量的 Lagrange 恒等式与向量三重积公式
rng(0);
N = 1000;
err_lag = zeros(N, 1);
err_trp = zeros(N, 1);
for k = 1:N
    u = randn(1, 3); v = randn(1, 3); w = randn(1, 3);
    err_lag(k) = abs(norm(cross(u, v))^2 - (norm(u)^2 * norm(v)^2 - dot(u, v)^2));
    err_trp(k) = max(abs(cross(u, cross(v, w)) - (dot(u, w)*v - dot(u, v)*w)));
end
fprintf('Max Lagrange error: %.3e\n', max(err_lag));
fprintf('Max triple-product error: %.3e\n', max(err_trp));
```

**分析说明**：两项最大误差通常在 $10^{-14}$ 量级而非严格为零，这是因为计算机采用 IEEE 754 双精度浮点数（机器精度 $\varepsilon_{\text{mach}}\approx 2.22\times 10^{-16}$），浮点加减乘运算会产生舍入误差。数值验证只能检验有限样本在近似精度下是否未出现反例，既不能覆盖无穷多个实向量，也不能排除存在极罕见反例或微小系统偏差的可能，故不能代替严格数学证明。

