rng(1);
for trial = 1:3
    A = randn(2, 1); B = randn(2, 1); C = randn(2, 1);
    M = 2 * [(B - A)'; (C - A)'];
    rhs = [norm(B)^2 - norm(A)^2; norm(C)^2 - norm(A)^2];
    O = M \ rhs;
    R = norm(A - O);
    G = (A + B + C) / 3;
    H = A + B + C - 2 * O;

    % 检验 H 在三条高上
    orth_err = max(abs([dot(H-A, C-B), dot(H-B, A-C), dot(H-C, B-A)]));
    fprintf('Trial %d: orthocenter residual = %.3e\n', trial, orth_err);

    % 九点圆圆心与半径
    N = (O + H) / 2;
    t = linspace(0, 2*pi, 300);
    figure; hold on; grid on; axis equal;
    plot([A(1) B(1) C(1) A(1)], [A(2) B(2) C(2) A(2)], 'k-', 'LineWidth', 1.2);
    plot(N(1) + (R/2)*cos(t), N(2) + (R/2)*sin(t), 'b--', 'LineWidth', 1.1);
    plot([O(1) G(1) H(1)], [O(2) G(2) H(2)], 'r-o', 'LineWidth', 1.2);

    % 标出三边中点与三条高的垂足
    mids = [(B+C)/2, (C+A)/2, (A+B)/2];
    foot = @(P, Q, S) Q + (dot(P-Q, S-Q)/norm(S-Q)^2) * (S-Q);
    feet = [foot(A,B,C), foot(B,C,A), foot(C,A,B)];
    plot(mids(1,:), mids(2,:), 'gs', 'MarkerFaceColor', 'g');
    plot(feet(1,:), feet(2,:), 'm^', 'MarkerFaceColor', 'm');
    title(sprintf('Trial %d: Euler Line & Nine-Point Circle', trial));
end
```

重复运行（包括钝角三角形情形，此时 $O,H$ 均位于三角形外部）可见：$H$ 满足三高正交条件的残差为机器精度量级，三边中点与三条高的垂足均严格落在以 $OH$ 中点 $N$ 为圆心、$\frac R2$ 为半径的九点圆上。

