colors = {[0.2 0.5 0.9], [0.9 0.4 0.2], [0.2 0.7 0.4]};

for k = 1:size(cases, 1)
    A = cases{k, 2}; b = cases{k, 3};
    fprintf('\n=== %s ===\n', cases{k, 1});
    disp(rref([A b]));
    figure; hold on; grid on; view(3);
    for i = 1:3
        a = A(i, 1); c2 = A(i, 2); c3 = A(i, 3); d = b(i);
        if abs(c3) > 1e-12
            X = U; Y = V; Z = (d - a*X - c2*Y) / c3;
        elseif abs(c2) > 1e-12
            X = U; Z = V; Y = (d - a*X - c3*Z) / c2;
        else
            Y = U; Z = V; X = (d - c2*Y - c3*Z) / a;
        end
        surf(X, Y, Z, 'FaceColor', colors{i}, 'FaceAlpha', 0.4, 'EdgeColor', 'none');
    end
    title(cases{k, 1}); xlabel('x'); ylabel('y'); zlabel('z');
end
```

对照 `rref([A b])` 与三维图形可见：无解情形（1, 5, 6, 7）的阶梯形均含矛盾行 $[0,0,0\mid 1]$；交于同一直线（3）含 $2$ 个主元与 $1$ 个自由未知量；三平面重合（2）仅含 $1$ 个主元；交于一点（4）含 $3$ 个主元且唯一解为 $(1,1,1)^\top$。

